import{_ as a}from"./chunks/wireless.3n6Ubgci.js";import{_ as r,c as t,o as s,ae as o}from"./chunks/framework.BrQRMotl.js";const p=JSON.parse('{"title":"無線レッドストーンシステム","description":"","frontmatter":{},"headers":[],"relativePath":"ja/manual/wireless_redstone.md","filePath":"ja/manual/wireless_redstone.md"}'),i={name:"ja/manual/wireless_redstone.md"};function n(l,e,_,d,c,h){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="無線レッドストーンシステム" tabindex="-1">無線レッドストーンシステム <a class="header-anchor" href="#無線レッドストーンシステム" aria-label="Permalink to &quot;無線レッドストーンシステム&quot;">​</a></h1><p>この MOD は、簡潔で効率的なグローバル無線レッドストーン伝送ソリューションを提供し、大規模な建築やエリアを跨ぐ音楽システムの配線作業を大幅に簡素化します。</p><h2 id="コアブロック" tabindex="-1">コアブロック <a class="header-anchor" href="#コアブロック" aria-label="Permalink to &quot;コアブロック&quot;">​</a></h2><p><img src="'+a+'" alt="WirelessRedstone"></p><h3 id="_1-レッドストーン信号送信機-transmitter" tabindex="-1">1. レッドストーン信号送信機 (Transmitter) <a class="header-anchor" href="#_1-レッドストーン信号送信機-transmitter" aria-label="Permalink to &quot;1. レッドストーン信号送信機 (Transmitter)&quot;">​</a></h3><ul><li><strong>機能</strong>: 送信機がレッドストーン信号を受信（充填）すると、ワールド全体の無線ネットワークを起動します。</li><li><strong>仕組み</strong>: ワールド内に <strong>少なくとも1つ</strong> 充填状態の送信機が存在する限り、無線ネットワークは「オン」状態になります。</li></ul><h3 id="_2-レッドストーン信号受信機-receiver" tabindex="-1">2. レッドストーン信号受信機 (Receiver) <a class="header-anchor" href="#_2-レッドストーン信号受信機-receiver" aria-label="Permalink to &quot;2. レッドストーン信号受信機 (Receiver)&quot;">​</a></h3><ul><li><strong>機能</strong>: 無線ネットワークの状態を監視します。無線ネットワークが「オン」状態のとき、受信機は周囲に強度 15 のレッドストーン信号を出力します。</li><li><strong>仕組み</strong>: 受信機は通常のレッドストーン源として使用でき、音符ブロック、ドア、ピストンなどを動作させることができます。</li></ul><h2 id="使用シナリオ" tabindex="-1">使用シナリオ <a class="header-anchor" href="#使用シナリオ" aria-label="Permalink to &quot;使用シナリオ&quot;">​</a></h2><ul><li><strong>リモートコントロール</strong>: 中央制御コンソールに送信機を配置し、離れた場所にある音符ブロック配列を制御します。</li><li><strong>同期再生</strong>: 複数のエリアの受信機を対応する音符ブロックに接続し、1つのマスター信号を通じてエリア間の同期発音を実現します。</li></ul>',10)])])}const g=r(i,[["render",n]])